SELECT 



        (o.opp_no LIKE CONCAT('%', #{keyword}, '%') OR o.name LIKE CONCAT('%', #{keyword}, '%')
         OR c.name LIKE CONCAT('%', #{keyword}, '%'))

    AND o.stage = #{stage}
    AND o.stage NOT IN ('WON', 'LOST')
    AND o.stage = #{status}
    AND o.customer_id = #{customerId}
    AND o.owner_id = #{ownerId}
    AND o.campaign_id = #{campaignId}

ORDER BY CASE WHEN o.stage IN ('WON', 'LOST') THEN 1 ELSE 0 END, o.expected_date, o.id DESC
